DECLARE
  l_failures PLS_INTEGER := 0;
  l_actual NUMBER;
  l_expected NUMBER;

  PROCEDURE report_check(
    p_check_name VARCHAR2,
    p_input      NUMBER,
    p_expected   NUMBER,
    p_actual     NUMBER
  ) IS
    l_input_text    VARCHAR2(4000);
    l_expected_text VARCHAR2(4000);
    l_actual_text   VARCHAR2(4000);
  BEGIN
    l_input_text    := COALESCE(TO_CHAR(p_input), 'NULL');
    l_expected_text := COALESCE(TO_CHAR(p_expected), 'NULL');
    l_actual_text   := COALESCE(TO_CHAR(p_actual), 'NULL');

    IF (p_expected IS NULL AND p_actual IS NULL) OR p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_check_name ||
        ' input=' || l_input_text ||
        ' expected=' || l_expected_text ||
        ' actual=' || l_actual_text
      );
    ELSE
      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_check_name ||
        ' input=' || l_input_text ||
        ' expected=' || l_expected_text ||
        ' actual=' || l_actual_text
      );
    END IF;
  END report_check;

BEGIN
  SAVEPOINT test_savepoint;

  -- NULL input: CASE WHEN p_value < 0 is unknown, so the ELSE branch returns p_value.
  l_actual := HARNESS_APP.clamp_nonnegative(NULL);
  l_expected := NULL;
  report_check('NULL input', NULL, l_expected, l_actual);

  -- Negative input: should be clamped to zero.
  l_actual := HARNESS_APP.clamp_nonnegative(-42);
  l_expected := 0;
  report_check('Negative input', -42, l_expected, l_actual);

  -- Zero input: should remain zero.
  l_actual := HARNESS_APP.clamp_nonnegative(0);
  l_expected := 0;
  report_check('Zero input', 0, l_expected, l_actual);

  -- Positive input: should be returned unchanged.
  l_actual := HARNESS_APP.clamp_nonnegative(17);
  l_expected := 17;
  report_check('Positive input', 17, l_expected, l_actual);

  ROLLBACK TO test_savepoint;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'clamp_nonnegative tests failed: ' || l_failures);
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: unexpected error: ' || SQLCODE || ' - ' || SQLERRM
    );
    ROLLBACK TO test_savepoint;
    RAISE;
END;
```

The block calls the stored standalone function by name, `HARNESS_APP.clamp_nonnegative`, rather than copying its code into the test. It checks four cases: a `NULL` input, expecting `NULL`; a negative input, expecting `0`; zero, expecting `0`; and a positive input, expecting the same value back. Each check prints either `PASS` or `FAIL` with the input, expected value, and actual value, and increments a failure counter on mismatch. The block starts with a savepoint and rolls back to it before finishing; if any check failed, it raises an application error. Its exception handler also rolls back to the savepoint and re-raises unexpected errors. I have not run this block.

